  const clamp = (v, a, b) => Math.min(Math.max(v, a), Math.max(a, b));
  const side = fixed ? 'above' : vh - r.bottom >= ch + G + 12 ? 'below' : r.top >= ch + G + 12 ? 'above' : vw - r.right >= cw + G + 12 ? 'right' : r.left >= cw + G + 12 ? 'left' : 'in';
  let x, y;
